[URL Rewrite]
request if ${url} ~= /^https:\/\/gateway\.benewtech\.cn\/resources-app\/app\/startup\/prepage/i then reject_dict(200)
request if ${url} ~= /^https:\/\/ntt-app\.benewtech\.cn\/v6\/user\/\d+\/messages\/event/i then reject_dict(200)

[MITM]
hostname = %APPEND% gateway.benewtech.cn, ntt-app.benewtech.cn
